struct State { long long cost; int vertex; int discountUsed; };
struct StateOrder {
    bool operator()(const State& left, const State& right) const { return left.cost > right.cost; }
};

vector<vector<long long>> shortestCost(
    int vertexCount, const vector<vector<pair<int, long long>>>& graph, int sourceVertex) {
    const long long infinity = (1LL << 62);
    vector<vector<long long>> minimumCost(vertexCount, vector<long long>(2, infinity));
    priority_queue<State, vector<State>, StateOrder> pendingStates;
    minimumCost[sourceVertex][0] = 0;
    pendingStates.push({0, sourceVertex, 0});

    while (!pendingStates.empty()) {
        State currentState = pendingStates.top();
        pendingStates.pop();
        if (currentState.cost != minimumCost[currentState.vertex][currentState.discountUsed]) continue;
        for (auto [nextVertex, edgeCost] : graph[currentState.vertex]) {
            int sameState = currentState.discountUsed;
            if (currentState.cost + edgeCost < minimumCost[nextVertex][sameState]) {
                minimumCost[nextVertex][sameState] = currentState.cost + edgeCost;
                pendingStates.push({minimumCost[nextVertex][sameState], nextVertex, sameState});
            }
            if (!currentState.discountUsed) {
                long long discountedCost = currentState.cost + edgeCost / 2;
                if (discountedCost < minimumCost[nextVertex][1]) {
                    minimumCost[nextVertex][1] = discountedCost;
                    pendingStates.push({discountedCost, nextVertex, 1});
                }
            }
        }
    }
    return minimumCost;
}
